class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = monthly_limit_mib * 1024 * 1024
        self._counted_names: dict[str, set[str]] = {}
        self._used: dict[str, int] = {}
        self._files: set[str] = set()
        self._owners: dict[str, str] = {}

    def upload(
        self, name: str, size_bytes: int, month: str, *, owner: str = ""
    ) -> None:
        if size_bytes <= 0:
            raise ValueError("Upload size must be positive")

        names = self._counted_names.get(month)
        if names is not None and name in names:
            self._files.add(name)
            self._owners[name] = owner
            return

        used = self._used.get(month, 0)
        if used + size_bytes > self._limit_bytes:
            raise ValueError("Monthly upload quota exceeded")

        self._counted_names.setdefault(month, set()).add(name)
        self._used[month] = used + size_bytes
        self._files.add(name)
        self._owners[name] = owner

    def delete(self, name: str, month: str) -> None:
        # Deletion does not change quota usage or permit a name to be
        # counted again in the same month.
        self._files.discard(name)
        self._owners.pop(name, None)

    def used_bytes(self, month: str) -> int:
        return self._used.get(month, 0)

    def remaining_bytes(self, month: str) -> int:
        return int(max(0, self._limit_bytes - self.used_bytes(month)))

    def files(self) -> list[str]:
        return sorted(self._files)

    def files_of(self, owner: str) -> list[str]:
        return sorted(name for name, file_owner in self._owners.items()
                      if file_owner == owner)
```

